-- ─────────────────────────────────────────────────────────────
-- Outfit AI — import van je Base44-data
--
-- Zet hieronder het e-mailadres van je account op de Plell-instantie.
-- Het gebruikers-id wordt automatisch opgezocht, zodat je niets hoeft
-- over te typen.
--
--   docker exec -i plell-db psql -U postgres -d postgres \
--     -v ON_ERROR_STOP=1 < import-outfit.sql
-- ─────────────────────────────────────────────────────────────

\set eigenaar_email 'luca.stoop@outlook.com'

-- De export gebruikt Base44-ids van 24 tekens; die passen niet in een
-- uuid-kolom. Omzetten naar tekst houdt ook de verwijzingen in
-- kledingstuk_ids heel.
alter table public.kledingstuk alter column id             type text using id::text;
alter table public.kledingstuk alter column id             set default gen_random_uuid()::text;
alter table public.outfit      alter column id             type text using id::text;
alter table public.outfit      alter column id             set default gen_random_uuid()::text;
alter table public.feedback    alter column id             type text using id::text;
alter table public.feedback    alter column id             set default gen_random_uuid()::text;
alter table public.feedback    alter column outfit_id      type text using outfit_id::text;
alter table public.geheugen    alter column id             type text using id::text;
alter table public.geheugen    alter column id             set default gen_random_uuid()::text;
alter table public.geheugen    alter column bron_outfit_id type text using bron_outfit_id::text;

begin;

-- ── kledingstuk.sql (65 regels) ──
• Te warm voor warme dagen. Draag je deze broek alleen bij hele specifieke gelegenheden — je geeft dit zelf aan in je dagplanning.
• Te warm voor warme dagen. Draag je dit alleen bij hele specifieke gelegenheden — je geeft het zelf aan wanneer je het wilt dragen.', 'BBL1', '2026-05-26T23:24:09.277Z');

-- ── geheugen.sql (7 regels) ──

Bij warm en actief weer, vanaf ongeveer 20°C, geef je duidelijk de voorkeur aan shorts boven een lange broek, ook bij regenkans. Een jas sla je dan over als je fysiek actief bezig bent. Deze voorkeuren leg je expliciet vast in je dagplanning, wat wijst op vaste patronen: je stemt je outfit bewust af op de activiteit, het weer en de formaliteit van de dag.', NULL, '2026-06-07T08:59:44.941Z');

-- ── feedback.sql (6 regels) ──
Met een T-shirt er onder. En een beetje nette broek maar dat zijn eigenlijk alle behalve joggingbroek.
