insert into public.geheugen (id, created_by, type, inhoud, bron_outfit_id, aangemaakt_op) values ('6a25337054377c2ecc10531a', (select id from auth.users where email = :'eigenaar_email'), 'leermoment', 'Bij een volledig zwarte outfit geef je de voorkeur aan zwarte schoenen boven blauw-witte sneakers voor meer kleursamenhang. Vermijd het mixen van donkerblauw met een all-black look.', '6a2533072b6c5d68130e7e24', '2026-06-07T09:01:35.956Z');
insert into public.geheugen (id, created_by, type, inhoud, bron_outfit_id, aangemaakt_op) values ('6a253301bdda73d7b2992f90', (select id from auth.users where email = :'eigenaar_email'), 'profiel_samenvatting', 'Jouw stijl is praktisch en situatiebewust. Op koude werkdagen draag je graag een quarterzip of coltrui over een T-shirt. Gekleurde pantalons, zoals een groene, bewaar je voor feestelijke of nette gelegenheden. Je lichtblauwe jeans en witte sneakers zet je in voor specifieke situaties zoals vuil werk of sporten — niet als dagelijkse outfit. Voor thuis studeren of werken kies je liever comfortabelere broeken met leren sneakers.
insert into public.geheugen (id, created_by, type, inhoud, bron_outfit_id, aangemaakt_op) values ('6a2532f9c92927eef95a70b3', (select id from auth.users where email = :'eigenaar_email'), 'leermoment', 'Je draagt quarterzip- of coltruitjes met een T-shirt eronder naar werk bij koud weer, terwijl gekleurde pantalons zoals de groene voor je gereserveerd zijn voor feestelijke of nette gelegenheden.', '6a2531709411a9eb8b8543c0', '2026-06-07T08:59:37.615Z');
insert into public.geheugen (id, created_by, type, inhoud, bron_outfit_id, aangemaakt_op) values ('6a19e2ca2d3e727f9cbf1313', (select id from auth.users where email = :'eigenaar_email'), 'leermoment', 'Je draagt de lichtblauwe jeans enkel bij specifieke gelegenheden en geeft dit expliciet aan in je dagplanning. Bij actieve dagen met temperaturen rond 20°C of hoger geef je de voorkeur aan een kortere broek.', '6a19e0b760133284e5b355df', '2026-05-29T19:02:33.867Z');
insert into public.geheugen (id, created_by, type, inhoud, bron_outfit_id, aangemaakt_op) values ('6a19e22e47f91a3e25acd66d', (select id from auth.users where email = :'eigenaar_email'), 'leermoment', 'Je draagt de lichtblauwe gewassen jeans alleen bij specifieke gelegenheden en geeft dit expliciet aan in je dagbeschrijving. Bij activiteiten zoals een jaarbeurs met fysiek werk en temperaturen rond 20-25°C geef je de voorkeur aan kortere broeken boven een lange broek.', '6a19e0b760133284e5b355df', '2026-05-29T18:59:57.934Z');
insert into public.geheugen (id, created_by, type, inhoud, bron_outfit_id, aangemaakt_op) values ('6a19b3d8928238624e363137', (select id from auth.users where email = :'eigenaar_email'), 'leermoment', 'Bij activiteiten die fysieke inspanning combineren met warm en vochtig weer geef je de voorkeur aan shorts boven een lange broek, zelfs bij regenkans. Een jas sla je bij dit soort dagen over als de temperatuur rond de 20°C ligt en je actief bezig bent.', '6a195df02448458816c4ddaa', '2026-05-29T15:42:16.076Z');
insert into public.geheugen (id, created_by, type, inhoud, bron_outfit_id, aangemaakt_op) values ('6a18b0736881eaf3388ff050', (select id from auth.users where email = :'eigenaar_email'), 'leermoment', 'Je draagt de lichtblauwe jeans en witte sneakers alleen in specifieke situaties (vuil werk of sporten), niet als dagelijkse outfit. Voor studie- en werkdagen thuis geef je de voorkeur aan je leren sneakers en comfortabelere broeken.', '6a18aaa66310992acec481bb', '2026-05-28T21:15:31.464Z');
insert into public.feedback (id, created_by, outfit_id, feedback_tekst, rating, aangemaakt_op) values ('6a25336626ef3a24eb848ab3', (select id from auth.users where email = :'eigenaar_email'), '6a2533072b6c5d68130e7e24', 'De outfit is goed maar als je hele outfit zwart is gebruik dan ook de zwarte leren schoenen niet de blauwe.', 4, '2026-06-07T09:01:25.845Z');
insert into public.feedback (id, created_by, outfit_id, feedback_tekst, rating, aangemaakt_op) values ('6a2532d52523d62aa682978c', (select id from auth.users where email = :'eigenaar_email'), '6a2531709411a9eb8b8543c0', 'Als het kouder is dan doe ik eigenlijk altijd naar werk een trui aan zoals de quaterzips en coltrui.
insert into public.feedback (id, created_by, outfit_id, feedback_tekst, rating, aangemaakt_op) values ('6a19e2c1c1d0533612ababf3', (select id from auth.users where email = :'eigenaar_email'), '6a19e0b760133284e5b355df', 'Alles is goed behalve de broek, het is veel te warm voor een lange broek en ik wil die broek echt alleen aan bij hele specifieke dingen dus als ik die broek aan wil dan zal ik dat er bij zeggen in de wat ga ik vandaag doen.
insert into public.feedback (id, created_by, outfit_id, feedback_tekst, rating, aangemaakt_op) values ('6a19e225bd3a5f21cbf03c1c', (select id from auth.users where email = :'eigenaar_email'), '6a19e0b760133284e5b355df', 'alles is goed behalve de broek, het is veel te warm voor een lange broek en ik wil die broek echt alleen aan bij hele specifieke dingen dus als ik die broek aan wil dan zal ik dat er bij zeggen in de wat ga ik vandaag doen.
insert into public.feedback (id, created_by, outfit_id, feedback_tekst, rating, aangemaakt_op) values ('6a19b3cb6677e512b6af1d4a', (select id from auth.users where email = :'eigenaar_email'), '6a195df02448458816c4ddaa', 'ik heb alles wat je had aangeraden aan gedaan behalve de broek en de jas.
insert into public.feedback (id, created_by, outfit_id, feedback_tekst, rating, aangemaakt_op) values ('6a18b0677f3cdd0a3418da3c', (select id from auth.users where email = :'eigenaar_email'), '6a18aaa66310992acec481bb', 'die spijkerbroek heb ik eigenlijk alleen aan als ik het moet want ik vind hem niet heel lekker zitten. dus ik had hem vroeger aan bij een andere baan waar hij een beetje vies moest worden en waar een pontalon en zo niet paste.
insert into public.outfit (created_by, id, datum, kledingstuk_ids, weer_context, agenda_context, activiteit_beschrijving, ai_redenering, feedback_tekst, rating, aangemaakt_op) values ((select id from auth.users where email = :'eigenaar_email'), '6a310cb20ce9c50e18f782de', '2026-06-16', '6a1625022ff481abb78ca126,6a16248af4937aa54ee9c0b5,6a16280417d7c0dea94522fa,6a162a7e1cdfe3d2003ed0db', 'licht bewolkt, 18°C tot 23°C (gem 20°C), max 0% kans op neerslag, wind 5 km/u. Verloop: 11:00: 19°C, licht bewolkt, 0% neerslag; 14:00: 20°C, licht bewolkt, 0% neerslag; 17:00: 23°C, zeer lichte bewolking, 0% neerslag; 20:00: 22°C, licht bewolkt, 0% neerslag; 23:00: 18°C, bewolkt, 0% neerslag', '14:00 – Elise de beamer uitleggen', 'Naar basisschool om licht in te hangen', 'Vandaag combineer je de SB1 (donkerblauwe geribde polo) met de BZL1 (zwarte pantalon) — een nette maar praktische keuze voor een dag met les (HvA), een activiteit op een basisschool waarbij je licht inhangt en een afspraak waarbij je Elise de beamer uitlegt. Die activiteiten vragen om een presentabele uitstraling met bewegingsvrijheid. De temperatuur loopt op naar 23°C ''s middags, maar omdat er geen regen is en de polo luchtig is, blijf je comfortabel. De SCB1 past prima bij deze look — het is geen all-black outfit dus de opmerking over blauwe schoenen speelt hier niet. De RBR1 is de standaard riemdraagvoorkeur en combineert goed met donkerblauwe en zwarte tinten.', NULL, NULL, '2026-06-16T08:43:30.131Z');
insert into public.outfit (created_by, id, datum, kledingstuk_ids, weer_context, agenda_context, activiteit_beschrijving, ai_redenering, feedback_tekst, rating, aangemaakt_op) values ((select id from auth.users where email = :'eigenaar_email'), '6a2533072b6c5d68130e7e24', '2026-06-07', '6a1cc14f58d909ede6226758,6a1cbb2e467782ead06ea5c5,6a1b28774cb887529a8d42fc,6a16280417d7c0dea94522fa,6a162a7e1cdfe3d2003ed0db', 'bewolkt, 15°C tot 19°C (gem 17°C), max 20% kans op neerslag, wind 16 km/u', '12:00 – Werk Luca; hele dag – Weddenschap kabinet; hele dag – Weddenschap kabinet', 'Werk', 'Luca gaf in eerdere feedback aan dat hij bij werk naar koeler weer altijd een quarter-zip of coltrui aantrekt met een T-shirt eronder — de OVZ2 met de SZK1 eronder is precies die laagjescombo. De BZL2 (linnen broek) is licht en luchtig, netjes genoeg voor werk. De SCB1 zijn zijn vaste dagelijkse leren sneakers die hij al eerder als ''top'' beoordeelde, gecombineerd met de RBR1 als nette afwerking.', 'De outfit is goed maar als je hele outfit zwart is gebruik dan ook de zwarte leren schoenen niet de blauwe.', 4, '2026-06-07T08:59:50.813Z');
insert into public.outfit (created_by, id, datum, kledingstuk_ids, weer_context, agenda_context, activiteit_beschrijving, ai_redenering, feedback_tekst, rating, aangemaakt_op) values ((select id from auth.users where email = :'eigenaar_email'), '6a2531709411a9eb8b8543c0', '2026-06-07', '6a16248af4937aa54ee9c0b5,6a1627076c9e5bf76160d5dd,6a16280417d7c0dea94522fa,6a162a7e1cdfe3d2003ed0db,6a1cc763655605ca3d47742e', 'bewolkt, 15°C tot 19°C (gem 17°C), max 20% kans op neerslag, wind 16 km/u', '12:00 – Werk Luca; hele dag – Weddenschap kabinet; hele dag – Weddenschap kabinet', 'Werk', 'Vandaag werk je als theatertechnicus — een omgeving waar je zowel fysiek actief bent als contact hebt met collega''s, dus smart-casual past goed. De SB1 (jouw favoriete polo) combineert met de BGR1 pantalon. De SCB1 leren sneakers zijn jouw dagelijkse go-to. Voor de koelere ochtend pak je de OVB8 donkerblauwe vest met rits erbij.', 'Als het kouder is dan doe ik eigenlijk altijd naar werk een trui aan zoals de quaterzips en coltrui.
insert into public.outfit (created_by, id, datum, kledingstuk_ids, weer_context, agenda_context, activiteit_beschrijving, ai_redenering, feedback_tekst, rating, aangemaakt_op) values ((select id from auth.users where email = :'eigenaar_email'), '6a21517dff9756537dff9caa', '2026-06-04', '6a16290f6f1489feddffd31b,6a162827a09e90b5c015d6a8,6a1627e6d9e533eb7470ce7e', 'lichte regen, 15°C tot 18°C (gem 17°C), max 100% kans op neerslag, wind 24 km/u', 'geen afspraken', 'Ik ga niet naar studie.
insert into public.outfit (created_by, id, datum, kledingstuk_ids, weer_context, agenda_context, activiteit_beschrijving, ai_redenering, feedback_tekst, rating, aangemaakt_op) values ((select id from auth.users where email = :'eigenaar_email'), '6a2150fbd42ff46e54b8ec71', '2026-06-04', '6a1cbed70f359eadedd18afb,6a16290f6f1489feddffd31b,6a1627e6d9e533eb7470ce7e', 'lichte regen, 15°C tot 18°C (gem 17°C), max 100% kans op neerslag, wind 24 km/u', 'geen afspraken', 'Ik ga niet naar studie.
insert into public.outfit (created_by, id, datum, kledingstuk_ids, weer_context, agenda_context, activiteit_beschrijving, ai_redenering, feedback_tekst, rating, aangemaakt_op) values ((select id from auth.users where email = :'eigenaar_email'), '6a1fe75d8e70f167f971436c', '2026-06-03', '6a1cc14f58d909ede6226758,6a1b27fbfa3b163152f877fb,6a1627076c9e5bf76160d5dd,6a16284883ff909d25a2eb92,6a162a7e1cdfe3d2003ed0db,6a1627e6d9e533eb7470ce7e', 'lichte regen, 16°C tot 18°C (gem 17°C), max 100% kans op neerslag, wind 22 km/u', '15:00 – Werk Luca', 'Werk', 'Vandaag werk je als theatertechnicus, het regent de hele dag en het is 16–18°C. De SZ2 (dunne polo) als basislaag onder de OVZ2 (quarter-zip) geeft je flexibiliteit. De BGR1 (pantalon) is netter dan shorts; de SCZ2 (hoge wandelschoenen) is de enige echt waterbestendige schoen. De JZ2 (lichtere gewatteerde jas) is precies goed bij 17°C met regen.', NULL, NULL, '2026-06-03T08:35:40.884Z');
insert into public.outfit (created_by, id, datum, kledingstuk_ids, weer_context, agenda_context, activiteit_beschrijving, ai_redenering, feedback_tekst, rating, aangemaakt_op) values ((select id from auth.users where email = :'eigenaar_email'), '6a1e6f8d8b58cf5997cabce8', '2026-06-02', '6a1cc4d7ea74d875d94828e6,6a1627076c9e5bf76160d5dd,6a16280417d7c0dea94522fa,6a162a7e1cdfe3d2003ed0db,6a1627e6d9e533eb7470ce7e', 'lichte regen, 14°C tot 18°C (gem 16°C), max 100% kans op neerslag, wind 12 km/u', 'geen afspraken', 'Studie', 'Vandaag heb je de hele dag lichte regen en 14–18°C. De OVGR6 (dunne v-hals sweater) is perfect voor deze temperatuur. Je hebt studie (HvA), dus smart-casual past goed — de BGR1 pantalon combineert netjes. De SCB1 leren sneakers houden beter stand bij natte straten. Voor de regen raad ik de JZ2 (dunne gewatteerde jas) aan.', NULL, NULL, '2026-06-02T05:52:13.087Z');
insert into public.outfit (created_by, id, datum, kledingstuk_ids, weer_context, agenda_context, activiteit_beschrijving, ai_redenering, feedback_tekst, rating, aangemaakt_op) values ((select id from auth.users where email = :'eigenaar_email'), '6a1d3d2f9ca316ac21971a71', '2026-06-01', '6a1cbed70f359eadedd18afb,6a16290f6f1489feddffd31b,6a16280417d7c0dea94522fa,6a162a7e1cdfe3d2003ed0db', 'onbewolkt, 18°C tot 21°C (gem 20°C), max 0% kans op neerslag, wind 14 km/u', '11:00 – Kar terug ggs2', 'Studie', 'Het is een studiedag (HvA) met een korte klus, bij aangenaam lenteweer van 20–21°C en geen regen. Op basis van je feedback kies je bij rond 20°C bewust voor shorts boven een lange broek, dus de BZK1 is logisch; de SZ3 (dunne zwarte polo) sluit daarop aan. De SCB1 zijn je dagelijkse leren sneakers, en de RBR1 maakt de look af.', NULL, NULL, '2026-06-01T08:05:03.140Z');
insert into public.outfit (created_by, id, datum, kledingstuk_ids, weer_context, agenda_context, activiteit_beschrijving, ai_redenering, feedback_tekst, rating, aangemaakt_op) values ((select id from auth.users where email = :'eigenaar_email'), '6a1c0be35996bdd41919e0b7', '2026-05-31', '6a16248af4937aa54ee9c0b5,6a16290f6f1489feddffd31b,6a16280417d7c0dea94522fa,6a162a7e1cdfe3d2003ed0db', 'lichte regen, 17°C tot 23°C (gem 21°C), max 68% kans op neerslag, wind 15 km/u', 'geen afspraken', 'Even werken aan studie in de stad en dan thuis', 'Vandaag is het een casual studiedag, met temperaturen tot 23°C en lichte regen. Je draagt bij dit soort temperaturen liever een short — de BZK1. De SBK2 (donkerblauwe geribde polo) was eerder goedgekeurd. Voor schoeisel kies ik de SCB2 (leren sneakers), bij 68% neerslag waterbestendiger dan canvas.', NULL, NULL, '2026-05-31T10:22:27.445Z');
insert into public.outfit (created_by, id, datum, kledingstuk_ids, weer_context, agenda_context, activiteit_beschrijving, ai_redenering, feedback_tekst, rating, aangemaakt_op) values ((select id from auth.users where email = :'eigenaar_email'), '6a1b2bc7713fbaf2b4c70933', '2026-05-30', '6a16248af4937aa54ee9c0b5,6a16290f6f1489feddffd31b,6a16280417d7c0dea94522fa,6a162a7e1cdfe3d2003ed0db', 'bewolkt, 15°C tot 22°C (gem 19°C), max 97% kans op neerslag, wind 10 km/u', '10:00 – Werk', 'Werk en thuis', 'Vandaag werk je als theatertechnicus en het wordt warm (tot 22°C) met regen op meerdere momenten. De SBK2 + SCB2 + RBR1 combinatie was top, en bij rond 20°C en actief werk geef je voorkeur aan shorts — de BZK1. De JZ1 laat ik weg: te benauwd bij warm en vochtig weer.', NULL, NULL, '2026-05-30T18:26:15.402Z');
insert into public.outfit (created_by, id, datum, kledingstuk_ids, weer_context, agenda_context, activiteit_beschrijving, ai_redenering, feedback_tekst, rating, aangemaakt_op) values ((select id from auth.users where email = :'eigenaar_email'), '6a19e0b760133284e5b355df', '2026-05-29', '6a16248af4937aa54ee9c0b5,6a162b996b1f5bd1e169021c,6a16280417d7c0dea94522fa,6a162a7e1cdfe3d2003ed0db', 'bewolkt, 16°C tot 25°C (gem 20°C), max 0% kans op neerslag, wind 5 km/u', '08:30 – Career day; 15:00 – Spullen naar ggs2 lentemarkt', 'Naar jaarbeurs en dan zware spullen tillen', 'De agenda bevat een Career Day (smart-casual) én zware spullen tillen, dus de outfit moet representatief én functioneel zijn. De SBK2 (donkerblauwe geribde polo) past bij de Career Day. Gezien het oploopt naar 25°C is een lange broek gepast voor het professionele deel. De SCB2 leren sneakers zijn je go-to. De RBR1 riem maakt de look af. Geen jas bij 19–25°C en 0% neerslag.', 'Alles is goed behalve de broek, het is veel te warm voor een lange broek en ik wil die broek echt alleen aan bij hele specifieke dingen dus als ik die broek aan wil dan zal ik dat er bij zeggen in de wat ga ik vandaag doen.
insert into public.outfit (created_by, id, datum, kledingstuk_ids, weer_context, agenda_context, activiteit_beschrijving, ai_redenering, feedback_tekst, rating, aangemaakt_op) values ((select id from auth.users where email = :'eigenaar_email'), '6a195df02448458816c4ddaa', '2026-05-29', '6a16248af4937aa54ee9c0b5,6a1627076c9e5bf76160d5dd,6a16280417d7c0dea94522fa,6a162a7e1cdfe3d2003ed0db,6a1627e6d9e533eb7470ce7e', 'lichte regen, gemiddeld 20°C, 81% kans op neerslag, wind 7 km/u', '08:30 – Career day; 15:00 – Spullen naar ggs2 lentemarkt', 'Naar jaarbeurs en dan zware spullen tillen', 'Vandaag heb je een Career Day én zwaar tilwerk, dus je outfit moet representatief en functioneel zijn. De donkerblauwe geribde polo met de donkergroene pantalon en gevlochten riem geeft een verzorgde look. Voor het tillen en de regen beschermt de zwarte gewatteerde (zomer)jas je goed.', 'ik heb alles wat je had aangeraden aan gedaan behalve de broek en de jas.
insert into public.outfit (created_by, id, datum, kledingstuk_ids, weer_context, agenda_context, activiteit_beschrijving, ai_redenering, feedback_tekst, rating, aangemaakt_op) values ((select id from auth.users where email = :'eigenaar_email'), '6a18aaa66310992acec481bb', '2026-05-28', '6a1629fc3462979d236f5ff4,6a162b996b1f5bd1e169021c,6a16284883ff909d25a2eb92,6a16257d943ea00243021e2c', 'lichte regen, gemiddeld 20°C, 100% kans op neerslag, wind 11 km/u', '14:00 – Oc om; 17:00 – ding rommy', 'Naar studie en thuis werken', 'Vandaag is het 20°C met lichte regen. Je hebt colleges aan de HvA en daarna twee afspraken, dus smart-casual past goed. De donkerblauwe gebreide trui is dun genoeg voor 20°C. De lichtblauwe jeans is comfortabel voor een lange dag. Bij 100% neerslagkans kies ik makkelijk te drogen schoeisel. De riem maakt het geheel af.', 'die spijkerbroek heb ik eigenlijk alleen aan als ik het moet want ik vind hem niet heel lekker zitten. dus ik had hem vroeger aan bij een andere baan waar hij een beetje vies moest worden en waar een pontalon en zo niet paste.
